try:
    with db:  # one transaction: commit if every step works, roll back if any fails
        for name, change in ((body.from_vault, -body.amount), (body.to_vault, body.amount)):
            cur = db.execute("UPDATE vaults SET gold = gold + ? WHERE name = ?", (change, name))
            if cur.rowcount == 0:
                raise HTTPException(status_code=404, detail="No such vault")
except IntegrityError:
    raise HTTPException(status_code=409, detail="The vault rules say no") from None
